export type DecorCard = {
	id: string;
	title: string;
	image: string;
	rating: string;
	reviews: number;
	tags: string[];
};

export type CategoryPageData = {
	slug: string;
	title: string;
	subtitle: string;
	heroImage: string;
	cards: DecorCard[];
};

const cardTitleTemplates = [
	'Signature Setup',
	'Premium Theme Setup',
	'Elegant Backdrop Setup',
	'Grand Entry Setup',
	'Classic Celebration Setup',
	'Luxury Balloon Styling',
	'Minimal Chic Setup',
	'Deluxe Party Styling',
];

const cardTagTemplates = [
	['Premium', 'Indoor', 'Quick Setup'],
	['Theme Based', 'Indoor', 'Popular'],
	['Elegant', 'Home Event', 'Quick Setup'],
	['Grand', 'Outdoor', 'Premium'],
	['Classic', 'Home Event', 'Value Pick'],
	['Luxury', 'Indoor', 'Photogenic'],
	['Minimal', 'Indoor', 'Budget Friendly'],
	['Deluxe', 'Outdoor', 'Trending'],
];

const cardRatingTemplates = ['4.9', '4.8', '4.9', '5.0', '4.8', '4.7', '4.9', '4.8', '5.0', '4.9', '4.8', '4.9'];
const cardReviewTemplates = [124, 89, 203, 145, 92, 178, 112, 198, 134, 167, 105, 142, 189, 95];

const createCards = (slug: string, title: string, imagePool: string[]): DecorCard[] => {
	const baseTitle = title.replace('Decoration', '').trim();

	// If no images in pool, return fallback empty array
	if (!imagePool || imagePool.length === 0) return [];

	return imagePool.map((imagePath, index) => {
		// Extract original file name from Azure URL for the title
		const parts = imagePath.split('/');
		const filename = decodeURIComponent(parts[parts.length - 1] || '');
		let cardTitle = filename.replace(/\.[^/.]+$/, "").trim() || `${baseTitle} Setup ${index + 1}`;
		
		return {
			id: `${slug}-${index + 1}`,
			title: cardTitle,
			image: imagePath,
			rating: cardRatingTemplates[index % cardRatingTemplates.length],
			reviews: cardReviewTemplates[index % cardReviewTemplates.length],
			tags: cardTagTemplates[index % cardTagTemplates.length],
		};
	});
};

